// ASTRA contract — NEVER throw before responding; route violations to a 400.
const body = $json.body ?? $json;
const idempotencyKey = body.idempotencyKey || body.correlationId || null;
const now = new Date().toISOString();
if (!idempotencyKey) {
  return [{ json: { contractViolation: true, code: 'CONTRACT_VIOLATION', message: 'idempotencyKey required (at-least-once delivery + idempotent consumer)' } }];
}
return [{ json: {
  contractViolation: false,
  event: 'ORDER_LAB',
  orderId: body.orderId || idempotencyKey,
  patientId: body.patientId,
  uhid: body.uhid,
  tests: body.tests ?? [],
  priority: body.priority || 'routine',
  idempotencyKey,
  correlationId: body.correlationId,
  status: 'ACKNOWLEDGED',
  receivedAt: now,
  acknowledgedAt: now,
  source: body.source || 'astra-copilot',
  ackSource: 'n8n-order-lab'
} }];
